                finalSnapshot.HandCount,
                finalSnapshot.OutstandingStolenResource,
                finalSnapshot.Turn,
                finalSnapshot.ShufflesCrossed,
                finalSnapshot.BoundaryReason,
                finalSnapshot.PredictionGaps.ToArray())
            {
